import React, { useState, useEffect, useRef, useCallback } from 'react';
import { VideoOff, Clock, Volume2 } from 'lucide-react';
import { VoiceEngine } from '../ai/VoiceEngine';
import { SpeechSynthesisEngine } from '../ai/SpeechSynthesis';
import { generateInterviewQuestions, scoreAnswerWithAI } from '../ai/GeminiAI';

const VideoInterviewPage = ({ candidate, onComplete, onBack }) => {
  const [stream, setStream] = useState(null);
  const [isRecording, setIsRecording] = useState(false);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [questions, setQuestions] = useState([]);
  const [timeRemaining, setTimeRemaining] = useState(null);
  const [transcript, setTranscript] = useState('');
  const [isAISpeaking, setIsAISpeaking] = useState(false);
  const [status, setStatus] = useState('initializing');
  const [error, setError] = useState('');

  const videoRef = useRef(null);
  const voiceEngine = useRef(null);
  const speechEngine = useRef(null);
  const timerRef = useRef(null);
  const answersRef = useRef([]);

  // Cleanup media and engines
  const cleanup = useCallback(() => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
    }
    voiceEngine.current?.stop();
    speechEngine.current?.stop();
    if (timerRef.current) clearInterval(timerRef.current);
  }, [stream]);

  // Text-to-speech
  const speakText = useCallback(async (text) => {
    if (!speechEngine.current) return;
    setIsAISpeaking(true);
    try {
      await speechEngine.current.speak(text, {
        rate: 0.9,
        onEnd: () => setIsAISpeaking(false),
      });
    } catch (err) {
      console.error('Speech error:', err);
      setIsAISpeaking(false);
    }
  }, []);

  // Complete interview
  const completeInterview = useCallback(async () => {
    setStatus('completed');
    const totalScore = answersRef.current.reduce((sum, ans) => sum + ans.score, 0);
    await speakText(`Interview complete! Your total score is ${totalScore} points. Thank you for your time.`);
    setTimeout(() => onComplete({
      ...candidate,
      answers: answersRef.current,
      completed: true,
      completedAt: Date.now(),
      summary: `Total Score: ${totalScore} points`,
    }), 3000);
  }, [candidate, onComplete, speakText]);

  // Submit answer
  const handleSubmitAnswer = useCallback(async () => {
    if (!isRecording && status !== 'answering') return;

    const finalTranscript = voiceEngine.current?.stop() || transcript;
    setIsRecording(false);
    setStatus('evaluating');
    if (timerRef.current) clearInterval(timerRef.current);

    const question = questions[currentQuestionIndex];
    if (!question) return;

    const result = await scoreAnswerWithAI(
      question.question,
      finalTranscript || '(No answer provided)',
      question.difficulty
    );

    const newAnswer = {
      questionId: question.id,
      question: question.question,
      answer: finalTranscript,
      score: result.score,
      feedback: result.feedback,
      difficulty: question.difficulty,
      timeUsed: question.time - (timeRemaining || 0),
    };

    answersRef.current = [...answersRef.current, newAnswer];

    await speakText(`You scored ${result.score} points. ${result.feedback}`);

    if (currentQuestionIndex < questions.length - 1) {
      await speakText('Moving to the next question.');
      setTimeout(() => {
        const nextIndex = currentQuestionIndex + 1;
        const nextQuestion = questions[nextIndex];

        setCurrentQuestionIndex(nextIndex);
        setTimeRemaining(nextQuestion.time);
        setTranscript('');
        setStatus('asking');

        speakText(`Question ${nextIndex + 1}. ${nextQuestion.question}. You have ${nextQuestion.time} seconds to answer.`)
          .then(() => setTimeout(() => {
            // Start recording for next question
            if (!voiceEngine.current) voiceEngine.current = new VoiceEngine();

            voiceEngine.current.setCallbacks({
              onResult: (result) => setTranscript(result.full),
              onSilence: handleSubmitAnswer,
              onError: (err) => console.error('Voice error:', err),
            });

            const started = voiceEngine.current.start();
            if (started) {
              setIsRecording(true);
              setStatus('answering');
              // Start timer
              if (timerRef.current) clearInterval(timerRef.current);
              timerRef.current = setInterval(() => {
                setTimeRemaining(prev => {
                  if (prev <= 1) {
                    handleSubmitAnswer();
                    return 0;
                  }
                  return prev - 1;
                });
              }, 1000);
            }
          }, 1000));
      }, 2000);
    } else {
      completeInterview();
    }
  }, [currentQuestionIndex, questions, timeRemaining, transcript, isRecording, status, speakText, completeInterview]);

  // Start a question - using useCallback without dependencies to avoid circular deps
  const startQuestion = useCallback((index, questionList) => {
    const question = questionList[index];
    if (!question) return;

    setCurrentQuestionIndex(index);
    setTimeRemaining(question.time);
    setTranscript('');
    setStatus('asking');

    speakText(`Question ${index + 1}. ${question.question}. You have ${question.time} seconds to answer.`)
      .then(() => setTimeout(() => {
        // Start recording
        if (!voiceEngine.current) voiceEngine.current = new VoiceEngine();

        voiceEngine.current.setCallbacks({
          onResult: (result) => setTranscript(result.full),
          onSilence: handleSubmitAnswer,
          onError: (err) => console.error('Voice error:', err),
        });

        const started = voiceEngine.current.start();
        if (started) {
          setIsRecording(true);
          setStatus('answering');
          // Start timer
          if (timerRef.current) clearInterval(timerRef.current);
          timerRef.current = setInterval(() => {
            setTimeRemaining(prev => {
              if (prev <= 1) {
                handleSubmitAnswer();
                return 0;
              }
              return prev - 1;
            });
          }, 1000);
        }
      }, 1000));
  }, [speakText]); // eslint-disable-line react-hooks/exhaustive-deps

  // Initialize interview
  const initializeInterview = useCallback(async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: { width: 1280, height: 720 },
        audio: true,
      });

      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;

      voiceEngine.current = new VoiceEngine();
      speechEngine.current = new SpeechSynthesisEngine();
      await speechEngine.current.initialize();

      setStatus('generating_questions');
      const qs = await generateInterviewQuestions(
        `Name: ${candidate.name}\nEmail: ${candidate.email}`,
        'Software Developer'
      );
      setQuestions(qs);
      setStatus('ready');

      await speakText('Welcome to your video interview! We will start with the first question shortly. Please make sure your microphone is working.');

      setTimeout(() => startQuestion(0, qs), 2000);

    } catch (err) {
      console.error('Initialization error:', err);
      setError('Failed to access camera/microphone. Please grant permissions.');
      setStatus('error');
    }
  }, [candidate.name, candidate.email, speakText, startQuestion]);

  useEffect(() => {
    initializeInterview();
    return cleanup;
  }, [initializeInterview, cleanup]);

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  if (status === 'error') {
    return (
      <div className="min-h-screen bg-gray-900 flex items-center justify-center p-6">
        <div className="bg-white rounded-xl p-8 max-w-md text-center">
          <VideoOff className="w-16 h-16 text-red-500 mx-auto mb-4" />
          <h2 className="text-2xl font-bold text-gray-800 mb-2">Camera Access Required</h2>
          <p className="text-gray-600 mb-6">{error}</p>
          <button
            onClick={onBack}
            className="bg-indigo-600 text-white px-6 py-3 rounded-lg hover:bg-indigo-700 transition"
          >
            Go Back
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-900 p-6">
      <div className="max-w-6xl mx-auto">
        {/* Video Section */}
        <div className="bg-black rounded-xl overflow-hidden mb-6 relative">
          <video ref={videoRef} autoPlay playsInline muted className="w-full h-[400px] object-cover" />

          {/* Status Overlay */}
          <div className="absolute top-4 left-4 right-4 flex justify-between items-start">
            <div className="bg-black bg-opacity-70 px-4 py-2 rounded-lg">
              <div className="flex items-center gap-2 text-white">
                <div className={`w-3 h-3 rounded-full ${isRecording ? 'bg-red-500 animate-pulse' : 'bg-gray-500'}`} />
                <span className="text-sm font-medium">
                  {status === 'initializing' && 'Initializing...'}
                  {status === 'generating_questions' && 'Generating Questions...'}
                  {status === 'ready' && 'Ready to Start'}
                  {status === 'asking' && 'AI Speaking...'}
                  {status === 'answering' && 'Recording Your Answer'}
                  {status === 'evaluating' && 'Evaluating...'}
                  {status === 'completed' && 'Interview Complete!'}
                </span>
              </div>
            </div>

            {timeRemaining !== null && (
              <div className={`px-4 py-2 rounded-lg font-bold text-lg ${timeRemaining <= 30 ? 'bg-red-500' : 'bg-blue-500'} text-white`}>
                <Clock className="w-5 h-5 inline mr-2" />
                {formatTime(timeRemaining)}
              </div>
            )}
          </div>

          {isAISpeaking && (
            <div className="absolute bottom-4 left-4">
              <div className="bg-purple-500 px-4 py-2 rounded-lg flex items-center gap-2 text-white">
                <Volume2 className="w-5 h-5 animate-pulse" />
                <span className="font-medium">AI Speaking...</span>
              </div>
            </div>
          )}
        </div>

        {/* Question & Progress */}
        <div className="bg-white rounded-xl p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-gray-800">
              Question {currentQuestionIndex + 1} of {questions.length}
            </h2>
            <span className={`px-3 py-1 rounded-full text-sm font-semibold ${
              questions[currentQuestionIndex]?.difficulty === 'Easy' ? 'bg-green-100 text-green-700'
              : questions[currentQuestionIndex]?.difficulty === 'Medium' ? 'bg-yellow-100 text-yellow-700'
              : 'bg-red-100 text-red-700'}`}>
              {questions[currentQuestionIndex]?.difficulty}
            </span>
          </div>
          <p className="text-lg text-gray-700 mb-4">{questions[currentQuestionIndex]?.question || 'Loading question...'}</p>
          <div className="w-full bg-gray-200 rounded-full h-2">
            <div className="bg-indigo-600 h-2 rounded-full transition-all duration-300" style={{ width: `${((currentQuestionIndex + 1) / questions.length) * 100}%` }} />
          </div>
        </div>

        {/* Transcript */}
        {transcript && (
          <div className="bg-white rounded-xl p-6 mb-6">
            <h3 className="text-lg font-bold text-gray-800 mb-3">Your Answer (Live Transcript)</h3>
            <p className="text-gray-700 whitespace-pre-wrap">{transcript}</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default VideoInterviewPage;
